def solve(g):
    g=[row[:] for row in g]; H=len(g); W=len(g[0]); orig=[row[:] for row in g]
    for d in ('h','v'):
        # direction d='h': find horizontal bars (runs>=2 of same color on a row); extend vertically
        if d=='h':
            seen=set(); 
            for r in range(H):
                c=0
                while c<W:
                    if g[r][c]:
                        s=c; v=g[r][c]; 
                        while c+1<W and g[r][c+1]==v: c+=1; e=c
                        if e-s+1>=2:
                            for cc in range(s,e+1):
                                cs=[r2 for r2 in range(H) if orig[r2][cc]==v]
                                for r2 in cs:
                                    if g[r2][cc]==0: g[r2][cc]=v
                        else: c+=1
                    else: c+=1
        else:
            for c in range(W):
                r=0
                while r<H:
                    if g[r][c]:
                        s=r; v=g[r][c]
                        while r+1<H and g[r+1][c]==v: r+=1; _=None
                        e=r
                        if e-s+1>=2:
                            for rc in range(s,e+1):
                                cs=[cc2 for cc2 in range(W) if orig[rc2][c]==v]
                                for cc in cs:
                                    if g[rc][cc]==0: g[rc][cc]=v
                        else: r+=1
                    else: r+=1
    return g

for n in (1,2,3):
    gi=G[f'Demo pair {n} input']; go=G[f'Demo pair {n} output']
    m=solve(gi)
    bad=[(r,c,m[r][c],go[r][c]) for r in range(15) for c in range(15) if m[r][c]!=go[r][c]]
